import type { RawCommands } from './../../tiptap/index.js';
import { liftTarget } from './../../tiptap/pm/transform.js';

declare module './../../tiptap/core' {
  interface Commands<ReturnType> {
    normalizeNodes: {
      /**
       * Normalize nodes to a simple paragraph (keeps attrs).
       */
      normalizeNodes: () => ReturnType;
    };
  }
}

export const normalizeNodes: RawCommands['normalizeNodes'] =
  () =>
  ({ state, tr, dispatch }) => {
    const { selection } = tr;
    const { ranges } = selection;

    if (!dispatch) {
      return true;
    }

    ranges.forEach(({ $from, $to }) => {
      state.doc.nodesBetween($from.pos, $to.pos, (node, pos) => {
        if (node.type.isText) {
          return;
        }

        const { doc, mapping } = tr;
        const $mappedFrom = doc.resolve(mapping.map(pos));
        const $mappedTo = doc.resolve(mapping.map(pos + node.nodeSize));
        const nodeRange = $mappedFrom.blockRange($mappedTo);

        if (!nodeRange) {
          return;
        }

        const targetLiftDepth = liftTarget(nodeRange);

        if (node.type.isTextblock) {
          const { defaultType } = $mappedFrom.parent.contentMatchAt($mappedFrom.index());

          // the only difference from tiptap clearNodes, keep the attrs
          tr.setNodeMarkup(nodeRange.start, defaultType, node.attrs);
        }

        if (targetLiftDepth || targetLiftDepth === 0) {
          tr.lift(nodeRange, targetLiftDepth);
        }
      });
    });

    return true;
  };
