const toExternalPluginToolbarButtons = ({
  buttons,
  editor,
  publicCommands,
  modals,
}: {
  buttons: RicosPluginToolbarButton[];
  editor: Editor;
  publicCommands: PublicCommands;
  modals: ModalService;
}) => {
  return buttons.reduce((acc, toolbarButton) => {
    const { button, services } = toolbarButton;
    const { content } = services;

    const attributes = fromEntries(
      Object.entries(button.attributes || {}).map(([key, value]) => {
        return value ? [key, content.resolve(value)] : [key, undefined];
      })
    );

    if (attributes.visible === false) {
      return acc;
    }

    return {
      ...acc,
      [button.id]:
        button.type === 'separator'
          ? {
              type: 'separator',
              getIcon: () => button.icon,
              getLabel: () => {},
              onClick: () => {},
              isActive: () => false,
              isDisabled: () => false,
            }
          : {
              type: button.type,
              tooltip: services.t(
                (typeof button.tooltip === 'function'
                  ? button.tooltip({ isActive: !!attributes.active })
                  : button.tooltip) || ''
              ),
              toolbars: [],
              getIcon: () =>
                'getIcon' in button
                  ? button.getIcon?.({ services, attributes })
                  : 'icon' in button
                    ? button.icon
                    : undefined,
              getLabel: () =>
                'label' in button && button.label ? services.t(button.label) : undefined,
              onClick: (e: $TSFixMe) => {
                const returnValue = button?.command?.({
                  referenceElement: e?.referenceElement ?? e?.target,
                  tiptapEditor: editor,
                  publicCommands,
                  attributes,
                  modals,
                  isMobile: services.context.isMobile,
                  getComponentProps:
                    'getComponentProps' in button ? button.getComponentProps : undefined,
                });

                const node = attributes.selectedNode;
                services.pluginsEvents.publishPluginToolbarClick({
                  pluginId: node?.type?.name,
                  nodeId: node?.attrs?.id,
                  buttonName: button?.id,
                  value: e?.value,
                });

                return returnValue;
              },
              componentProps:
                'getComponentProps' in button
                  ? button.getComponentProps?.({
                      tiptapEditor: editor,
                      attributes,
                      publicCommands,
                      t: services.t,
                      modals,
                      languageDir: services.context.languageDir,
                    })
                  : undefined,
              isActive: () => !!attributes.active,
              isDisabled: () => !!attributes.disabled,
              dataHook: button.dataHook,
              name: button.id,
            },
    };
  }, {});
};

const getToolbarConfig = (
  toolbarSettings: ToolbarSettings | undefined,
  toolbarType: ToolbarType
) => {
  const finalToolbarSettings = initToolbarSettings(toolbarSettings);
  const toolbarConfig = finalToolbarSettings.find(setting => setting.name === toolbarType);
  return toolbarConfig;
};

const toExternalTextButtonsToolbarItemsConfig = (
  toolbarConfig: ToolbarSettingsFunctions | undefined,
  textButtons: TextButton[],
  toolbarType: ToolbarType | 'WIXEL',
  buttonsType: 'desktop' | 'mobile'
) => {
  if (!toolbarConfig) {
    console.error(`${toolbarType} doesn't exists`);
    return [];
  }

  const buttonsListFromConfig = getButtonsListFromConfig(toolbarConfig, buttonsType);

  const buttonsList = buttonsListFromConfig
    .map(handleDeprecatedButtons)
    .map(mapButtonsFromConfig)
    .map(toSchemaBasedId);

  const externalToolbarItemsConfig = buttonsList.flatMap(button => {
    const buttonConfig = textButtons.find(b => b.id === button);
    if (buttonConfig) {
      return [buttonConfig];
    }
    return [];
  });

  return externalToolbarItemsConfig;
};

const handleDeprecatedButtons = (configButtonId: string | { name: string }) => {
  if (typeof configButtonId === 'string') {
    return configButtonId;
  }
  if (configButtonId.name === 'Alignment') {
    return FORMATTING_BUTTONS.ALIGNMENT;
  }
};

const toExternalToolbarTextButtonConfig = (
  button: TextButton,
  publicCommands: PublicCommands,
  editor: TiptapEditor,
  editorQuery: IEditorQuery,
  services: PluginServices,
  tooltipHint?: string
): ToolbarButtonProps => {
  const attributes = toResolvedAttributes(button);
  const { modals, content, context, t, pluginsEvents, styles } = services;
  const name =
    button.id in toExternalType
      ? toExternalType[button.id as keyof typeof toExternalType]
      : button.id;

  if (button.type === 'separator') {
    return {
      type: 'separator',
      getIcon: () => button.presentation.icon,
    };
  }

  return {
    type: button.type,
    tooltip: `${t(button.presentation.tooltip)} ${tooltipHint ? `(${tooltipHint})` : ''}`,
    toolbars: [],
    componentProps:
      button.type === 'dropdown'
        ? (button.presentation.getComponentProps?.({
            publicCommands,
            t,
            modals,
            styles,
            editor,
          }) as Record<string, any>)
        : undefined,
    getIcon: () =>
      'getIcon' in button.presentation
        ? button.presentation.getIcon({ publicCommands, t })
        : button.presentation.icon,
    getLabel: () => t(name),
    onClick: e => {
      pluginsEvents.publishers.byTopic('ricos.toolbars.functionality.buttonClick').publish({
        toolbarType: ToolbarType.EXTERNAL,
        buttonId: button.id,
      });

      const referenceElement = e?.referenceElement ?? e?.target;

      return button.command?.({
        publicCommands,
        modalService: modals,
        editor,
        editorQuery,
        referenceElement,
        isMobile: context.isMobile,
        componentProps:
          'getComponentProps' in button.presentation
            ? button.presentation.getComponentProps({
                publicCommands,
                t,
                modals,
                editor,
                styles,
              })
            : undefined,
      })({});
    },
    isActive: () => !!attributes.active && !!content.resolve(attributes.active),
    isDisabled: () => !!attributes.disabled && !!content.resolve(attributes.disabled),
    dataHook: button.presentation?.dataHook,
    name,
  };
};

const toExternalType = {
  [Decoration_Type.BOLD]: FORMATTING_BUTTONS.BOLD,
  [Decoration_Type.ITALIC]: FORMATTING_BUTTONS.ITALIC,
  [Decoration_Type.UNDERLINE]: FORMATTING_BUTTONS.UNDERLINE,
  [Decoration_Type.STRIKETHROUGH]: FORMATTING_BUTTONS.STRIKETHROUGH,
  [`${Node_Type.HEADING}.title`]: FORMATTING_BUTTONS.TITLE,
  [Node_Type.BLOCKQUOTE]: FORMATTING_BUTTONS.BLOCKQUOTE,
  'TextAlignment.ALIGNMENT': FORMATTING_BUTTONS.ALIGNMENT,
  'TextAlignment.LEFT': FORMATTING_BUTTONS.ALIGN_LEFT,
  'TextAlignment.CENTER': FORMATTING_BUTTONS.ALIGN_CENTER,
  'TextAlignment.RIGHT': FORMATTING_BUTTONS.ALIGN_RIGHT,
  'TextAlignment.JUSTIFY': FORMATTING_BUTTONS.ALIGN_JUSTIFY,
  [Node_Type.ORDERED_LIST]: FORMATTING_BUTTONS.ORDERED_LIST,
  [Node_Type.BULLETED_LIST]: FORMATTING_BUTTONS.UNORDERED_LIST,
  [Node_Type.CHECKBOX_LIST]: FORMATTING_BUTTONS.CHECKBOX_LIST,
  [Decoration_Type.FONT_SIZE]: FORMATTING_BUTTONS.FONT_SIZE,
  [Decoration_Type.SPOILER]: FORMATTING_BUTTONS.SPOILER,
  [Decoration_Type.LINK]: FORMATTING_BUTTONS.LINK,
  [`${Node_Type.HEADING}.dropdown`]: FORMATTING_BUTTONS.HEADINGS,
  [`${Decoration_Type.COLOR}.foreground`]: FORMATTING_BUTTONS.TEXT_COLOR,
  [`${Decoration_Type.COLOR}.background`]: FORMATTING_BUTTONS.TEXT_HIGHLIGHT,
  [Node_Type.CODE_BLOCK]: FORMATTING_BUTTONS.CODE_BLOCK,
  LINE_SPACING: FORMATTING_BUTTONS.LINE_SPACING,
  [`INDENT.increase`]: FORMATTING_BUTTONS.INCREASE_INDENT,
  [`INDENT.decrease`]: FORMATTING_BUTTONS.DECREASE_INDENT,
};

const isPluginToolbarVisible = (selection: Selection | null, doc: ProseMirrorNode): boolean => {
  if (!selection || selection.empty || !(selection instanceof NodeSelection)) {
    return false;
  }

  try {
    let hasNonEmptyParagraph = false;
    doc.nodesBetween(selection.from, selection.to, node => {
      if (node.type.name === 'text' && node.text !== '') {
        hasNonEmptyParagraph = true;
        return false;
      }
    });

    return hasNonEmptyParagraph && isTextSelection(selection);
  } catch (error) {
    console.error('Error checking if plugin toolbar is visible', error);
    return false;
  }
};
