import type { RicosEditorProps } from './../ricos-common/index.js';
import type { PmContentContextType } from './../ricos-context/pm-content-context.js';
import type { SelectionContextType } from './../ricos-context/selection-context.js';
import type { ToolbarState } from './../ricos-context/toolbar-context.js';
import type { ModalState } from './../ricos-modals/modal-service.js';
import { type ExtensionProps, type RicosServices } from './../ricos-types/index.js';
import { getSelectedNodes } from './../_shared/get-selected-nodes.js';
import type { SelectorContextValue } from './../_shared/use-context-selector.js';
import { Editor } from './../tiptap/core/index.js';
import type { InlineAiContextType } from './../plugin-inline-ai/inline-ai-context.js';

import { invokeAtomicBlockFocus } from '../_shared/invoke-atomic-block-focus.js';
import { RichContentAdapter } from './components/rich-content-adapter.js';
import { applyDevTools } from './components/RicosTiptapEditor/apply-dev-tools.js';
import { coreConfigs } from './components/RicosTiptapEditor/core-configs.js';
import { createTiptapExtensions } from './models/create-tiptap-extensions.js';
import { transformPastedHTML } from './transform-pasted-html.js';

export type TiptapAdapterServices = Omit<RicosServices, 'editor' | 'zIndexService'>;

const extractExtensionProps = (props: RicosEditorProps): ExtensionProps => {
  const {
    placeholder,
    textAlignment,
    iframeSandboxDomain,
    textWrap,
    maxTextLength,
    linkSettings,
    generalLinkSettings,
    theme,
  } = props;

  let { anchorTarget, relValue, rel } = linkSettings || {};
  if (generalLinkSettings?.initialLinkOptions) {
    const { target, ...rest } = generalLinkSettings.initialLinkOptions;
    anchorTarget = target;
    rel = rest;
  }
  return {
    placeholder,
    textAlignment,
    iframeSandboxDomain,
    isTextWrap: textWrap,
    maxTextLength,
    anchorTarget,
    rel,
    relValue,
    breakoutRule: theme?.breakout?.rule,
  };
};

export const initializeTiptapAdapter = (
  ricosEditorProps: RicosEditorProps,
  services: TiptapAdapterServices,
  isDebugMode = false,
  getToolbarStateSelectorContextValue: () => SelectorContextValue<ToolbarState>,
  getSelectionSelectorContextValue: () => SelectorContextValue<SelectionContextType>,
  getModalStateSelectorContextValue: () => SelectorContextValue<ModalState>,
  pmContentSelectorContextValue: () => SelectorContextValue<PmContentContextType>,
  getInlineAiStateSelectorContextValue: () => SelectorContextValue<InlineAiContextType>
) => {
  // Check if collab plugin is present - if so, skip initial content to prevent double source of truth
  const hasCollabPlugin = services.plugins
    .asArray()
    .some(plugin => (plugin as any).plugin.name === 'collab');
  const tiptapContent = hasCollabPlugin ? null : services.schema.getTiptapContent();

  const extensionProps = extractExtensionProps(ricosEditorProps);
  const extensions = [...services.plugins.getTiptapExtensions(), ...coreConfigs];
  const tiptapExtensions = createTiptapExtensions(extensions, extensionProps, services);
  const { autofocus, onLoad, onAtomicBlockFocus } = ricosEditorProps;

  const editor = new Editor({
    extensions: tiptapExtensions as any,
    content: tiptapContent,
    injectCSS: true,
    editorProps: {
      transformPastedHTML,
    },
    onCreate({ editor }) {
      if (onLoad) {
        onLoad({ editor });
        if (autofocus) {
          invokeAtomicBlockFocus({
            selectedNodes: getSelectedNodes(editor),
            onAtomicBlockFocus,
          });
        }
      }
    },
    ...(autofocus && { autofocus }),
  });

  applyDevTools(editor, isDebugMode);

  return new RichContentAdapter(
    editor,
    services,
    ricosEditorProps.toolbarSettings,
    getToolbarStateSelectorContextValue,
    getSelectionSelectorContextValue,
    getModalStateSelectorContextValue,
    pmContentSelectorContextValue,
    getInlineAiStateSelectorContextValue
  );
};
