import { useContext, useEffect } from 'react';

import { RicosContext, SchemaContext } from './../../../ricos-context/index.js';
import { debounce } from './../../../_shared/debounce.js';
import { getSelectedNodes } from './../../../_shared/get-selected-nodes.js';
import { isSSR } from './../../../wix-rich-content-common/index.js';

import type { RicosTiptapEditorProps } from '../../types.js';

export const useEditorSideEffects = ({
  editor,
  onUpdate,
  onSelectionUpdate,
}: {
  editor: RicosTiptapEditorProps['editor'];
  onUpdate: RicosTiptapEditorProps['onUpdate'];
  onSelectionUpdate: RicosTiptapEditorProps['onSelectionUpdate'];
}) => {
  const schema = useContext(SchemaContext);
  const { content } = useContext(RicosContext);

  useEffect(() => {
    if (onUpdate) {
      // Only register the listener if there's a consumer — the body calls
      // `schema.getContent()` which serialises the entire doc and is the
      // dominant per-transaction cost on large docs.
      editor.on(
        'update',
        debounce(
          () => {
            onUpdate({
              content: schema.getContent(),
              pmContent: schema.getTiptapContent(),
            });
          },
          60,
          { leading: true }
        )
      );
    }
    editor.on(
      'selectionUpdate',
      debounce(
        () => {
          const selectedNodes = getSelectedNodes(editor);
          content.update(selectedNodes, editor);
          if (onSelectionUpdate) {
            onSelectionUpdate({
              selectedNodes,
              content: schema.getContent(),
              pmContent: schema.getTiptapContent(),
            });
          }
        },
        60,
        { leading: true }
      )
    );

    if (!isSSR()) {
      //@ts-ignore
      window.tiptapEditor = editor;
    }
  }, []);
};
