import cx from 'classnames';
import type { FunctionComponent } from 'react';
import React, { useContext, useMemo, useReducer, useState } from 'react';

import { or } from './../../../ricos-content/index.js';
import { EditorQueryContext, RicosContext, useTrackRender } from './../../../ricos-context/index.js';
import { getToolbarSettings, useToolbarSettings } from './../../../ricos-context/toolbar-context.js';
import { StylesContext } from './../../../ricos-styles/index.js';
import { ToolbarType } from './../../../ricos-types/index.js';
import { getPluginIdByInsertPlugin } from './../../../_shared/get-plugin-id-by-insert-plugin.js';
/* oxlint-disable jsx-a11y/no-noninteractive-tabindex */
/* oxlint-disable jsx-a11y/no-static-element-interactions */
import { EditorContent } from './../../../tiptap/react/index.js';
import { getLangDir } from './../../../wix-rich-content-common/index.js';
import { RICOS_TIPTAP_EDITOR_DATA_HOOK } from './../../../editor-common/index.js';
import { FloatingAddPluginMenu } from './../../../toolbars-v3/index.js';
import { useIsToolbarEmpty } from './../../../toolbars-v3/ricos-toolbars/use-is-toolbar-empty.js';

import { RicosTiptapContext } from '../../context.js';
import styles from '../../statics/styles/tiptap-editor-styles-scss.js';
import type { RicosTiptapEditorProps } from '../../types.js';
import { focusReducer } from './focus-reducer.js';
import { useEditorSideEffects } from './use-editor-side-effects.js';
import { useJsdomWidthFix } from './use-jsdom-width-fix.js';
import { useKeydownListener } from './use-keydown-listener.js';

export const editorFocusDescriptionId = 'editor-container-tooltip';

export const RicosTiptapEditor: FunctionComponent<RicosTiptapEditorProps> = props => {
  const {
    editor,
    onUpdate,
    onSelectionUpdate,
    editorStyleClasses,
    htmlAttributes,
    preserveDomOnUnmount,
    ...context
  } = props;
  const { localeContent, lastInteraction, t, tabFocusBehavior } = useContext(RicosContext);
  const { stylePreset } = useContext(StylesContext);
  const [ref, setRef] = useState<HTMLDivElement | null>(null);
  const [state, dispatch] = useReducer(focusReducer, 'not-focused');

  useTrackRender('RicosTiptapEditor');
  useJsdomWidthFix(ref, editor);
  useEditorSideEffects({ editor, onUpdate, onSelectionUpdate });

  const handleKeyDown = (event: KeyboardEvent) => {
    if (event.key !== 'Escape') {
      dispatch({ type: 'keydown', event });
      return;
    }

    const currentSelection = editor.state.selection;

    setTimeout(() => {
      // If the selection has changed, Escape was handled by other component
      if (!currentSelection.eq(editor.state.selection)) {
        return;
      }

      dispatch({ type: 'keydown', event });
    }, 0);
  };

  const handleMouseDown = () => {
    dispatch({ type: 'pointer-focus' });
  };

  useKeydownListener(ref, handleKeyDown);

  const ricosTiptapContextValue = useMemo(() => {
    return {
      context: {
        t: context.t,
        theme: context.theme,
        onLoad: context.onLoad,
        devToolsElement: context.devToolsElement,
      },
    };
  }, [context.t, context.theme, context.onLoad, context.devToolsElement]);

  return (
    <RicosTiptapContext.Provider value={ricosTiptapContextValue}>
      <div
        data-hook={RICOS_TIPTAP_EDITOR_DATA_HOOK}
        dir={getLangDir(localeContent)}
        className={cx(
          editorStyleClasses?.containerClassName,
          styles.ricosTiptapEditor,
          {
            [styles.focusRing]:
              state === 'editor-focused-outlined' ||
              state === 'container-focused' ||
              state === 'awaiting-keyboard-input',
          },
          stylePreset
        )}
        style={
          state === 'container-focused' || state === 'awaiting-keyboard-input'
            ? { caretColor: 'transparent' }
            : {}
        }
        onMouseDown={handleMouseDown}
        onBlur={() => {
          dispatch({ type: 'blur' });
        }}
        onFocus={() => {
          const getKeyboardFocusType = () => {
            if (tabFocusBehavior === 'container') {
              return 'keyboard-focus-awaiting';
            }
            return 'keyboard-focus';
          };
          dispatch({
            type: lastInteraction === 'keyboard' ? getKeyboardFocusType() : 'pointer-focus',
          });
        }}
        {...htmlAttributes}
        tabIndex={-1}
        ref={setRef}
      >
        <FloatingPluginMenu isMobile={context.isMobile} />
        <EditorContent
          editor={editor}
          className={editorStyleClasses?.editorClassName}
          preserveDomOnUnmount={preserveDomOnUnmount}
        />
        {props.devToolsElement}
      </div>
      {(state === 'container-focused' || state === 'awaiting-keyboard-input') && (
        <span aria-live="assertive" role="alert" className={styles.srOnly}>
          {t('Editor_Blur_Description')}
        </span>
      )}
      <span id={editorFocusDescriptionId} className={styles.srOnly}>
        {t('Editor_Focus_Description')}
      </span>
    </RicosTiptapContext.Provider>
  );
};

const FloatingPluginMenu: React.FC<{ isMobile: boolean }> = ({ isMobile }) => {
  const editorQuery = useContext(EditorQueryContext);
  const { isMultipleSelection, isSingleRootTextBlock } = editorQuery.query;
  const shouldShowPlusButton = or([isMultipleSelection, isSingleRootTextBlock]) as () => boolean;
  const sideToolbarSettings = useToolbarSettings(getToolbarSettings(ToolbarType.SIDE));
  const insertPluginToolbarSettings = useToolbarSettings(
    getToolbarSettings(ToolbarType.INSERT_PLUGIN)
  );
  const supportedButtonIds = insertPluginToolbarSettings
    ?.getButtons?.()
    ?.desktop?.map(getPluginIdByInsertPlugin);

  const isToolbarEmpty = useIsToolbarEmpty(ToolbarType.SIDE);

  if (isMobile || isToolbarEmpty) {
    return null;
  }

  return (
    <FloatingAddPluginMenu
      onClick={sideToolbarSettings?.onClick}
      isVisible={shouldShowPlusButton}
      supportedButtonIds={supportedButtonIds}
    />
  );
};
