import { pipe } from 'fp-ts-esm/function';
import type { ComponentType } from 'react';
import React from 'react';

import type {
  ExtensionProps,
  HtmlRicosNodeExtension,
  PluginProps,
  ReactRicosNodeExtension,
  RicosExtension,
  RicosNodeExtension,
} from './../../ricos-types/index.js';
import { isRicosNodeExtension } from './../../ricos-types/index.js';
import type { AnyExtension, NodeViewRendererProps } from './../../tiptap/core/index.js';
import { mergeAttributes, Node } from './../../tiptap/core/index.js';
import { Plugin, PluginKey } from './../../tiptap/pm/state.js';
import type { NodeConfig } from './../../tiptap/react/index.js';
import { markInputRule, markPasteRule, textblockTypeInputRule } from './../../tiptap/react/index.js';

import { RicosNode } from '../components/ricos-node.js';
import type { TiptapAdapterServices } from '../initialize-tiptap-adapter.js';
import { DEFAULT_PRIORITY } from './constants.js';
import type { IFunctionalExtension } from './functional-extension.js';
import type { IMarkExtension } from './mark-extension.js';
import { NodeViewWrapper } from './node-view-wrapper.js';
import { ReactNodeViewRenderer } from './react-node-view.js';

export type IExtension =
  | IReactNodeExtension
  | IHtmlNodeExtension
  | IFunctionalExtension
  | IMarkExtension;

const toExtensionConfig = (ext: RicosNodeExtension) => {
  if (ext.type === 'html-node') {
    return ext.createExtensionConfig({
      textblockTypeInputRule,
      markPasteRule,
      markInputRule,
      mergeAttributes,
      Plugin,
      PluginKey,
    });
  }

  return ext.createExtensionConfig({
    textblockTypeInputRule,
    markPasteRule,
    markInputRule,
    mergeAttributes,
    Plugin,
    PluginKey,
  });
};

// @TODO: REWRITE THIS. If this was actually included in each respective node and handled by itself
// then we would have a normal text editor that you copy content from and in!!!
// This is horrible because content copied from us cannot be used in other editors!
const toFullNodeConfig =
  (ext: RicosNodeExtension) =>
  (config: NodeConfig): NodeConfig => {
    // omit addKeyboardShortcuts
    const { addKeyboardShortcuts, ...rest } = config;
    return {
      ...(ext.groups.includes('text')
        ? {}
        : {
            parseHTML: () => [
              {
                tag: `${config.name}-component`,
                getAttrs: node => {
                  const attrs = (node as any).getAttribute?.('data-node-attrs');
                  return JSON.parse(attrs);
                },
              },
            ],
            renderHTML: ({ HTMLAttributes }) => {
              return [
                `${config.name}-component`,
                {
                  'data-node-attrs': JSON.stringify(HTMLAttributes),
                },
                ...(ext.groups.includes('node-container') ? [0] : []),
              ];
            },
          }),
      ...rest,
      ...(ext.groups.includes('shortcuts-enabled') ? { addKeyboardShortcuts } : {}),
    };
  };

const createRicosNodeConfig = (ext: RicosNodeExtension): NodeConfig =>
  pipe(ext, toExtensionConfig, toFullNodeConfig(ext));

const createRicosNodeHOC =
  <T extends any = {}>(Component: ComponentType<T>, settings: Record<string, unknown>) =>
  (props: NodeViewRendererProps) => (
    <NodeViewWrapper as="div">
      <RicosNode Component={Component} tiptapNodeProps={{ ...props, settings }} />
    </NodeViewWrapper>
  );

export type IReactNodeExtension = ReactNodeExtension;

export class ReactNodeExtension {
  config: NodeConfig;

  priority: number;

  type = 'react-node' as const;

  name: string;

  groups: ReactRicosNodeExtension['groups'];

  protected readonly settings: Record<string, unknown>;

  private readonly ricosExtension: ReactRicosNodeExtension;

  protected readonly reconfigure: (
    config: NodeConfig,
    extensions: RicosExtension[],
    ricosProps: ExtensionProps,
    settings: Record<string, unknown>,
    services: TiptapAdapterServices
  ) => NodeConfig;

  constructor(extension: ReactRicosNodeExtension, config?: NodeConfig) {
    if (!isRicosNodeExtension(extension)) {
      throw new TypeError('invalid argument');
    }
    this.ricosExtension = extension;
    this.config = config || createRicosNodeConfig(extension);
    this.priority = this.config.priority || DEFAULT_PRIORITY;
    this.name = this.config.name;
    this.groups = extension.groups;
    this.settings = extension.settings || {};
    this.reconfigure = extension.reconfigure || (() => this.config);
  }

  getComponent(): ComponentType<PluginProps> {
    return this.ricosExtension.Component;
  }

  asRenderable<T = {}>(decoratedComponent: ComponentType<T>) {
    return new RenderableNodeExtension<T>(decoratedComponent, this.ricosExtension);
  }

  getRicosExtension(): RicosExtension {
    return this.ricosExtension;
  }
}

class RenderableNodeExtension<T = {}> extends ReactNodeExtension {
  constructor(component: ComponentType<T>, extension: ReactRicosNodeExtension) {
    super(extension);
    const ricosNodeHoc = createRicosNodeHOC(component, this.settings);
    this.config = {
      addNodeView: () => ReactNodeViewRenderer(ricosNodeHoc, extension.renderingOptions),
      ...this.config,
    };
  }

  toTiptapExtension(
    extensions: RicosExtension[],
    ricosProps: ExtensionProps,
    services: TiptapAdapterServices
  ): AnyExtension {
    const config = this.reconfigure(this.config, extensions, ricosProps, this.settings, services);
    return Node.create(config);
  }
}

export type IHtmlNodeExtension = HtmlNodeExtension;

export class HtmlNodeExtension {
  config: NodeConfig;

  priority: number;

  type = 'html-node' as const;

  name: string;

  private readonly ricosExtension: HtmlRicosNodeExtension;

  private readonly settings: Record<string, unknown>;

  private readonly reconfigure: (
    config: NodeConfig,
    extensions: RicosExtension[],
    ricosProps: ExtensionProps,
    settings: Record<string, unknown>,
    services: TiptapAdapterServices
  ) => NodeConfig;

  groups: HtmlRicosNodeExtension['groups'];

  constructor(extension: HtmlRicosNodeExtension, config?: NodeConfig) {
    if (!isRicosNodeExtension(extension)) {
      throw new TypeError('invalid argument');
    }
    this.ricosExtension = extension;
    this.config = config || createRicosNodeConfig(extension);
    this.priority = this.config.priority || DEFAULT_PRIORITY;
    this.name = this.config.name;
    this.groups = extension.groups || [];
    this.settings = extension.settings || {};
    this.reconfigure = extension.reconfigure || (() => this.config);
  }

  getRicosExtension(): RicosExtension {
    return this.ricosExtension;
  }

  toTiptapExtension(
    extensions: RicosExtension[],
    ricosProps: ExtensionProps,
    services: TiptapAdapterServices
  ): Node {
    const config = this.reconfigure(this.config, extensions, ricosProps, this.settings, services);
    return Node.create(config);
  }
}
