export const transformPastedHTML = (html: string) => {
  const parser = new DOMParser();
  const doc = parser.parseFromString(html, 'text/html');
  flattenNestedTables(doc.body);
  stripSmartBlockCellDecorations(doc.body);
  replaceTrailingSpacesWithNonBreakingSpaces(doc.body);

  return doc.body.innerHTML;
};

// A native/viewer copy of a smart block puts its *rendered* DOM on the clipboard,
// where each cell's decorative accessories (auto-number, shapes, stat labels) sit
// as siblings of the real content. On paste those would become stray PARAGRAPHs
// (e.g. the cell number on its own line), so keep only the marked content subtree.
// ProseMirror's own copy serializes the model — no marker — so its cells are untouched.
const stripSmartBlockCellDecorations = (root: Element) => {
  for (const cell of Array.from(root.querySelectorAll('[data-smart-block-cell]'))) {
    const content = cell.querySelector('[data-smart-block-content]');
    if (content) {
      cell.replaceChildren(content);
    }
  }
};

const flattenNestedTables = (root: Element) => {
  for (const cell of Array.from(root.querySelectorAll('td table, th table'))) {
    const fragment = document.createDocumentFragment();
    for (const innerCell of Array.from(cell.querySelectorAll('td, th'))) {
      while (innerCell.firstChild) {
        fragment.appendChild(innerCell.firstChild);
      }
    }
    cell.replaceWith(fragment);
  }
};

const replaceTrailingSpacesWithNonBreakingSpaces = (node: ChildNode) => {
  node.childNodes.forEach(child => {
    if (child.nodeType === Node.TEXT_NODE) {
      if (child?.nodeValue?.startsWith(' ')) {
        child.nodeValue = child.nodeValue.replace(/^\s+/g, match => match.replace(/ /g, '\u00A0'));
      }
    } else if (child.nodeType === Node.ELEMENT_NODE) {
      replaceTrailingSpacesWithNonBreakingSpaces(child);
    }
  });
};
