import type { EditorState } from 'prosemirror-state';
import { NodeSelection, TextSelection } from 'prosemirror-state';
import { canSplit } from 'prosemirror-transform';

import type { RawCommands } from './../../tiptap/index.js';

import { defaultBlockAt } from '../helpers/default-block-at.js';
import { getSplittedAttributes } from '../helpers/get-splitted-attributes.js';

function ensureMarks(state: EditorState, splittableMarks?: string[]) {
  const marks =
    state.storedMarks || (state.selection.$to.parentOffset && state.selection.$from.marks());

  if (marks) {
    const filteredMarks = marks.filter(mark => splittableMarks?.includes(mark.type.name));

    state.tr.ensureMarks(filteredMarks);
  }
}

declare module './../../tiptap/core' {
  interface Commands<ReturnType> {
    splitBlock: {
      /**
       * Forks a new node from an existing node.
       */
      splitBlock: (options?: { keepMarks?: boolean }) => ReturnType;
    };
  }
}

export const splitBlock: RawCommands['splitBlock'] =
  ({ keepMarks = true } = {}) =>
  ({ tr, state, dispatch, editor }) => {
    const { selection, doc } = tr;
    const { $from, $to } = selection;
    const extensionAttributes = editor.extensionManager.attributes;
    const newAttributes = getSplittedAttributes(
      extensionAttributes,
      $from.node().type.name,
      $from.node().attrs
    );

    if (selection instanceof NodeSelection && selection.node.isBlock) {
      if (!$from.parentOffset || !canSplit(doc, $from.pos)) {
        return false;
      }

      if (dispatch) {
        if (keepMarks) {
          ensureMarks(state, editor.extensionManager.splittableMarks);
        }

        tr.split($from.pos).scrollIntoView();
      }

      return true;
    }

    if (!$from.parent.isBlock) {
      return false;
    }

    if (dispatch) {
      const atEnd = $to.parentOffset === $to.parent.content.size;

      if (selection instanceof TextSelection) {
        tr.deleteSelection();
      }

      const deflt =
        $from.depth === 0
          ? undefined
          : defaultBlockAt($from.node(-1).contentMatchAt($from.indexAfter(-1)));

      const attrs = removeLevelAttribute(newAttributes);

      let types =
        atEnd && deflt
          ? [
              {
                type: deflt,
                attrs,
              },
            ]
          : undefined;

      let can = canSplit(tr.doc, tr.mapping.map($from.pos), 1, types);

      if (
        !types &&
        !can &&
        canSplit(tr.doc, tr.mapping.map($from.pos), 1, deflt ? [{ type: deflt }] : undefined)
      ) {
        can = true;
        types = deflt
          ? [
              {
                type: deflt,
                attrs: newAttributes,
              },
            ]
          : undefined;
      }

      if (can) {
        tr.split(tr.mapping.map($from.pos), 1, types);

        if (deflt && !atEnd && !$from.parentOffset && $from.parent.type !== deflt) {
          const first = tr.mapping.map($from.before());
          const $first = tr.doc.resolve(first);

          if ($from.node(-1).canReplaceWith($first.index(), $first.index() + 1, deflt)) {
            tr.setNodeMarkup(tr.mapping.map($from.before()), deflt);
          }
        }
      }

      if (keepMarks) {
        ensureMarks(state, editor.extensionManager.splittableMarks);
      }

      tr.scrollIntoView();
    }

    return true;
  };

const removeLevelAttribute = (attributes: Record<string, any>): Record<string, any> => {
  // oxlint-disable-next-line @typescript-oxlint/no-unused-vars
  const { level, ...attrs } = attributes;
  return attrs;
};
