import React, { useContext } from 'react';

import { NodeViewContent } from './../../tiptap/index.js';

import { RicosTiptapContext } from '../context.js';
import styles from '../statics/styles/tiptap-editor-styles-scss.js';
import { ErrorBoundary } from './error-boundary.js';

export const RicosNode = ({ Component, tiptapNodeProps }: $TSFixMe) => {
  const ricosTiptapContext = useContext(RicosTiptapContext) || {};

  const componentProps = {
    ...ricosTiptapContext, // helpers, editor Props
    componentData: tiptapNodeProps.node.attrs,
    ...tiptapNodeProps,
    NodeViewContent,
  };

  if (!ricosTiptapContext.context.t) {
    return null;
  }

  return (
    <div
      data-hook={`ricos-node editor-${tiptapNodeProps.node.attrs.id}`}
      className={styles['ricos-node']}
    >
      <ErrorBoundary t={ricosTiptapContext.context.t}>
        <Component {...componentProps} />
      </ErrorBoundary>
    </div>
  );
};
