import type { ExtensionProps, NodeHocDescriptor, RicosExtension } from './../../ricos-types/index.js';
import { unreachable } from './../../_shared/uncreachable.js';
import type { AnyExtension } from './../../tiptap/core/index.js';
import { Extension } from './../../tiptap/core/index.js';

import type { TiptapAdapterServices } from '../initialize-tiptap-adapter.js';
import { DEFAULT_PRIORITY } from './constants.js';
import type { IFunctionalExtension } from './functional-extension.js';
import { FunctionalExtension } from './functional-extension.js';
import type { IMarkExtension } from './mark-extension.js';
import { MarkExtension } from './mark-extension.js';
import type { IExtension, IHtmlNodeExtension, IReactNodeExtension } from './node-extension.js';
import { HtmlNodeExtension, ReactNodeExtension } from './node-extension.js';

// TODO: default extension should be FunctionalExtension with empty functionality
const defaultIExtension = {
  toTiptapExtension: Extension.create,
};

const toIExtension = (extension: RicosExtension, services: TiptapAdapterServices): IExtension => {
  switch (extension.type) {
    case 'react-node':
      return new ReactNodeExtension(extension);
    case 'html-node':
      return new HtmlNodeExtension(extension);
    case 'extension':
      return new FunctionalExtension(extension, services);
    case 'mark':
      return new MarkExtension(extension);
    default:
      unreachable(extension);
      return defaultIExtension as unknown as IExtension;
  }
};

const isFunctionalExtension = (extension: IExtension): extension is IFunctionalExtension =>
  extension.type === 'extension';

const isReactNodeExtension = (extension: IExtension): extension is IReactNodeExtension =>
  extension.type === 'react-node';

const isHtmlNodeExtension = (extension: IExtension): extension is IHtmlNodeExtension =>
  extension.type === 'html-node';

const isMarkExtension = (extension: IExtension): extension is IMarkExtension =>
  extension.type === 'mark';

const validateNames = (extensions: IExtension[]) => {
  const names = extensions.map(extension => extension.name);

  const duplicateNames = names
    .map(name => ({ name, duplicate: names.indexOf(name) !== names.lastIndexOf(name) }))
    .filter(({ duplicate }) => !!duplicate)
    .map(({ name }) => name);

  if (duplicateNames.length > 0) {
    throw new Error(`Extension name collision: ${duplicateNames.join(' ,')}`);
  }
};

const decorateReactNodeExtension = (
  extension: IReactNodeExtension,
  hocDescriptors: readonly NodeHocDescriptor[]
) => {
  const ricosExtension = extension.getRicosExtension();
  const Component = extension.getComponent();
  const DecoratedComponent = hocDescriptors
    .filter(desc => desc.nodeTypes?.includes(extension.name) || desc.nodeTypes?.includes('*'))
    .map(desc => desc.getNodeHoc(ricosExtension))
    .reduce((component, hoc) => hoc(component), Component);

  return extension.asRenderable(DecoratedComponent);
};

export const createTiptapExtensions = (
  ricosExtensions: readonly RicosExtension[],
  props: ExtensionProps,
  services: TiptapAdapterServices
): AnyExtension[] => {
  const sortedExtensions = ricosExtensions
    .map(extension => toIExtension(extension, services))
    .sort((a, b) => a.priority - b.priority); // asc

  validateNames(sortedExtensions);

  const sortedRicosExtensions = sortedExtensions.map(extension => extension.getRicosExtension());

  const hocDescriptors = sortedExtensions
    .filter(isFunctionalExtension)
    .map(extension => extension.getNodeHocDescriptor(sortedRicosExtensions, props, services))
    .filter(descriptor => !!descriptor)
    .sort((a, b) => (a.priority || DEFAULT_PRIORITY) - (b.priority || DEFAULT_PRIORITY)); // asc

  const reactNodes = sortedExtensions
    .filter(isReactNodeExtension)
    .map(extension => decorateReactNodeExtension(extension, hocDescriptors))
    .map(extension => extension.toTiptapExtension(sortedRicosExtensions, props, services));

  const htmlNodes = sortedExtensions
    .filter(isHtmlNodeExtension)
    .map(extension => extension.toTiptapExtension(sortedRicosExtensions, props, services));

  const marks = sortedExtensions
    .filter(isMarkExtension)
    .map(extension => extension.toTiptapExtension(sortedRicosExtensions, props, services));

  const extensions = sortedExtensions
    .filter(isFunctionalExtension)
    .map(extension => extension.toTiptapExtension(sortedRicosExtensions, props, services));

  // This order might be important, but the reasons for it are now lost to time...
  return [...extensions, ...marks, ...reactNodes, ...htmlNodes];
};
