import { createRicosFunctionalExtension } from './../tiptap-extensions/index.js';

import * as deleteNode from './commands/delete-node.js';
import * as insertNode from './commands/insert-node.js';
import * as normalizeNodes from './commands/normalize-nodes.js';
import * as replaceNode from './commands/replace-node.js';
import * as replaceNodes from './commands/replace-nodes.js';
import * as setNodeAttrsById from './commands/set-node-attrs-by-id.js';
import * as splitBlock from './commands/split-block.js';
import * as toggleTextNode from './commands/toggle-text-node.js';
import * as updateAttributesWithDeepMerge from './commands/update-attributes-with-deep-merge.js';
import * as updateNodeAttrsById from './commands/update-node-attrs-by-id.js';
import * as updateTextNode from './commands/update-text-node.js';

export const commands = createRicosFunctionalExtension({
  type: 'extension',
  groups: [],
  name: 'ricos-node-commands',
  createExtensionConfig() {
    return {
      name: this.name,
      addCommands() {
        return {
          ...insertNode,
          ...updateTextNode,
          ...toggleTextNode,
          ...normalizeNodes,
          ...setNodeAttrsById,
          ...updateNodeAttrsById,
          ...deleteNode,
          ...replaceNode,
          ...replaceNodes,
          ...updateAttributesWithDeepMerge,
          ...splitBlock,
        };
      },
    };
  },
});
