import type { ExtensionProps, RicosExtension } from './../../ricos-types/index.js';
import { isRicosMarkExtension } from './../../ricos-types/index.js';
import {
  isMarkActive,
  Mark,
  markInputRule,
  markPasteRule,
  mergeAttributes,
  textblockTypeInputRule,
} from './../../tiptap/core/index.js';
import { Plugin, PluginKey } from './../../tiptap/pm/state.js';
import type { MarkConfig } from './../../tiptap/react/index.js';

import type { TiptapAdapterServices } from '../initialize-tiptap-adapter.js';
import { DEFAULT_PRIORITY } from './constants.js';

export type IMarkExtension = MarkExtension;

export class MarkExtension {
  config: MarkConfig;

  priority: number;

  type = 'mark' as const;

  name: string;

  groups: RicosExtension['groups'];

  private readonly settings: Record<string, unknown>;

  private readonly reconfigure: (
    config: MarkConfig,
    extensions: RicosExtension[],
    ricosProps: ExtensionProps,
    settings: Record<string, unknown>,
    services: TiptapAdapterServices
  ) => MarkConfig;

  private readonly ricosExtension: RicosExtension;

  constructor(extension: RicosExtension, config?: MarkConfig) {
    if (!isRicosMarkExtension(extension)) {
      throw new TypeError('invalid argument');
    }
    this.groups = extension.groups || [];
    this.settings = extension.settings || {};
    const { addKeyboardShortcuts, ...rest } =
      config ||
      extension.createExtensionConfig({
        isMarkActive,
        textblockTypeInputRule,
        mergeAttributes,
        markInputRule,
        markPasteRule,
        Plugin,
        PluginKey,
      });
    this.config = {
      ...rest,
      ...(extension.groups.includes('shortcuts-enabled') ? { addKeyboardShortcuts } : {}),
      type: 'mark',
    };
    this.priority = this.config.priority || DEFAULT_PRIORITY;
    this.name = this.config.name;
    this.ricosExtension = extension;
    this.reconfigure = extension.reconfigure || (() => this.config);
  }

  getRicosExtension(): RicosExtension {
    return this.ricosExtension;
  }

  toTiptapExtension(
    extensions: RicosExtension[],
    ricosProps: ExtensionProps,
    services: TiptapAdapterServices
  ): Mark {
    const config = this.reconfigure(this.config, extensions, ricosProps, this.settings, services);
    return Mark.create(config);
  }
}
